"hljs-title class_\">B</span>();\n        a.printValue();\n        System.out.print(a.i);\n    }\n}</code></pre>|||<p>Kết quả in ra của chương trình Java sau là gì? (Lớp A khai báo int i = 100 và printValue() in ra &quot;A&quot;; lớp B kế thừa A, khai báo lại int i = 120 và ghi đè printValue() in ra &quot;B&quot;; trong Main tạo A a = new B(), gọi a.printValue() rồi in a.i)</p><pre><code class=\"language-java\"><span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">A</span>{\n    <span class=\"hljs-type\">int</span> <span class=\"hljs-variable\">i</span> <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">100</span>;\n    <span class=\"hljs-keyword\">public</span> <span class=\"hljs-keyword\">void</span> <span class=\"hljs-title function_\">printValue</span><span class=\"hljs-params\">()</span>{\n        System.out.print(<span class=\"hljs-string\">&quot;A&quot;</span>);\n    }\n}\n<span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">B</span> <span class=\"hljs-keyword\">extends</span> <span class=\"hljs-title class_\">A</span>{\n    <span class=\"hljs-type\">int</span> <span class=\"hljs-variable\">i</span> <span class=\"hljs-operator\">=</span> <span class=\"hljs-number\">120</span>;\n    <span class=\"hljs-keyword\">public</span> <span class=\"hljs-keyword\">void</span> <span class=\"hljs-title function_\">printValue</span><span class=\"hljs-params\">()</span>{\n        System.out.print(<span class=\"hljs-string\">&quot;B&quot;</span>);\n    }\n}\n<span class=\"hljs-keyword\">public</span> <span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">Main</span>{\n    <span class=\"hljs-keyword\">public</span> <span class=\"hljs-keyword\">static</span> <span class=\"hljs-keyword\">void</span> <span class=\"hljs-title function_\">main</span><span class=\"hljs-params\">(String args[])</span>{\n        <span class=\"hljs-type\">A</span> <span class=\"hljs-variable\">a</span> <span class=\"hljs-operator\">=</span> <span class=\"hljs-keyword\">new</span> <span class=\"hljs-title class_\">B</span>();\n        a.printValue();\n        System.out.print(a.i);\n    }\n}</code></pre>",
